#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string line;
    std::getline(std::cin, line);

    int braceWordCount = 0;
    int maxWordLen = 0;
    bool insideParentheses = false;
    std::string buffer;

    auto updateCounts = [&](const std::string& buf, bool inBraces) {
        int length = buf.length();
        if (length > 0) {
            if (inBraces) {
                braceWordCount++;
            } else {
                maxWordLen = std::max(maxWordLen, length);
            }
        }
    };

    for (int i = 0; i < n; ++i) {
        char c = line[i];

        if (c == '_') {
            updateCounts(buffer, insideParentheses);
            buffer.clear();
        } else if (c == '(') {
            updateCounts(buffer, insideParentheses);
            buffer.clear();
            insideParentheses = true;
        } else if (c == ')') {
            updateCounts(buffer, insideParentheses);
            buffer.clear();
            insideParentheses = false;
        } else if (std::isalpha(c)) {
            buffer += c;
        }
    }

    // After loop, process remaining buffer
    updateCounts(buffer, insideParentheses);

    std::cout << maxWordLen << " " << braceWordCount << std::endl;

    return 0;
}
